#!/usr/bin/env node
// On-demand Core UI doc fetcher for `@sdcorejs/angular` (or the legacy `@sd-angular/core`).
//
// The angular skills do NOT commit the Core UI component docs into this repo. Instead they
// pull the PUBLISHED docs at generation time — raw (never summarized), version-matched to the
// target project's installed package, and cached per version so repeated use is cheap/offline.
//
// Source of truth: https://sdcorejs.github.io/sdcorejs-angular/docs
//   - versions.json            → which versions are published (per Angular major 19/20/21)
//   - <version>/index.json     → the component inventory (what exists)
//   - <version>/<path>.md      → one component's full API doc
//
// Usage (run from inside the target Angular project so version auto-detects, or pass --version):
//   node core-docs-fetch.mjs --list                          # print the Core UI inventory
//   node core-docs-fetch.mjs sd-button                       # fetch one doc → print cached file path
//   node core-docs-fetch.mjs components/button/sd-button     # full id/path also works
//   node core-docs-fetch.mjs --print sd-select               # print the doc CONTENT to stdout
//   node core-docs-fetch.mjs --version 21.0.7 --list
//   node core-docs-fetch.mjs --cwd <target> --require-installed --list
//   node core-docs-fetch.mjs --cwd <target> --require-installed --exact-version --list
// --exact-version requires a resolved version, never falls back to another
// version, and fails clearly when those docs are unavailable. Verify installed
// source/exports before using APIs; nearest mode is reference discovery only.
//
// Cache (never committed): ~/.cache/sdcorejs/core-docs/<version>/...
// Offline: if the network is unavailable it falls back to cache; if neither, it exits non-zero
// with a clear message so the skill uses local Core UI evidence only. `--require-installed`
// fails before network/cache if the target project has no Core UI dependency.

import { get as httpsGet } from 'node:https';
import { mkdirSync, writeFileSync, readFileSync, existsSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, dirname, isAbsolute, normalize } from 'node:path';
import { pathToFileURL } from 'node:url';

const SITE = 'https://sdcorejs.github.io/sdcorejs-angular/docs';
const SITE_ORIGIN = new URL(SITE).origin;
const CACHE_ROOT = join(homedir(), '.cache', 'sdcorejs', 'core-docs');
const CORE_UI_PACKAGES = ['@sdcorejs/angular', '@sd-angular/core'];

// UTF-8-as-CP1252 mojibake signatures (never valid in clean VN/EN docs).
// Stored as escapes so this reusable script stays ASCII and locale-neutral.
const MOJIBAKE_PATTERNS = [
  '\u00e1\u00bb',
  '\u00e1\u00ba',
  '\u00c6\u00b0',
  '\u00c4\u2018',
  '\u00c3\u00a2',
  '\u00c3\u00a9',
  '\u00c3\u00ad',
  '\u00c3\u00b3',
  '\u00c3\u00ba',
  '\u00c3\u00ab',
  '\u00c3\u00a8',
  '\u00c3\u00b4',
  '\u00c3\u00a3',
  '\u00e2\u20ac\u201c',
  '\u00e2\u20ac\u0153',
  '\u00e2\u20ac\u2122',
  '\u00e2\u20ac\u00a6',
  '\u00ef\u00bf\u00bd',
];
const MOJIBAKE = new RegExp(MOJIBAKE_PATTERNS.join('|'));

// ── args ───────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
let version, cwd = process.cwd(), doList = false, doPrint = false, requireInstalled = false, exactVersion = false, comp;
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '--list') doList = true;
  else if (a === '--print') doPrint = true;
  else if (a === '--require-installed') requireInstalled = true;
  else if (a === '--exact-version') exactVersion = true;
  else if (a === '--version') version = args[++i];
  else if (a === '--cwd') cwd = args[++i];
  else if (!a.startsWith('--') && !comp) comp = a;
}

const cmpDesc = (a, b) => {
  const pa = a.split('-')[0].split('.').map(Number);
  const pb = b.split('-')[0].split('.').map(Number);
  for (let i = 0; i < 3; i++) if ((pb[i] || 0) !== (pa[i] || 0)) return (pb[i] || 0) - (pa[i] || 0);
  return 0;
};

function httpText(url) {
  return new Promise((resolve, reject) => {
    httpsGet(url, res => {
      if ([301, 302, 307, 308].includes(res.statusCode)) {
        res.resume();
        if (!res.headers.location) return reject(new Error(`HTTP ${res.statusCode} without Location for ${url}`));
        const nextUrl = new URL(res.headers.location, url);
        if (nextUrl.origin !== SITE_ORIGIN) {
          return reject(new Error(`Refusing redirect outside docs origin: ${nextUrl.href}`));
        }
        return resolve(httpText(nextUrl.href));
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error(`HTTP ${res.statusCode} for ${url}`));
      }
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    }).on('error', reject);
  });
}

function readJson(file) {
  try { return JSON.parse(readFileSync(file, 'utf8')); } catch { return null; }
}

function versionFromRange(range) {
  if (!range || typeof range !== 'string') return null;
  const exact = range.match(/(\d+\.\d+\.\d+)/);
  if (exact) return exact[1];
  const major = range.match(/(\d+)/);
  return major ? `${major[1]}.0.0` : null;
}

function versionFromPackageJson(file) {
  return packageFromPackageJson(file)?.version ?? null;
}

function packageFromPackageJson(file) {
  const j = readJson(file);
  if (!j) return null;
  const deps = { ...j.dependencies, ...j.devDependencies, ...j.peerDependencies, ...j.optionalDependencies };
  for (const name of CORE_UI_PACKAGES) {
    if (deps[name]) return { name, version: versionFromRange(deps[name]) };
  }
  return null;
}

function walkPackageJsons(root, depth = 4, acc = []) {
  if (depth < 0) return acc;
  let entries;
  try { entries = readdirSync(root, { withFileTypes: true }); } catch { return acc; }
  for (const entry of entries) {
    const full = join(root, entry.name);
    if (entry.isFile() && entry.name === 'package.json') {
      acc.push(full);
      continue;
    }
    if (!entry.isDirectory()) continue;
    if (['node_modules', '.git', 'dist', 'coverage', '.angular', '.cache'].includes(entry.name)) continue;
    walkPackageJsons(full, depth - 1, acc);
  }
  return acc;
}

function versionFromPackageJsons(root) {
  return packageFromPackageJsons(root)?.version ?? null;
}

function packageFromPackageJsons(root) {
  const rootPkg = join(root, 'package.json');
  const direct = packageFromPackageJson(rootPkg);
  if (direct) return direct;
  for (const pkg of walkPackageJsons(root)) {
    const found = packageFromPackageJson(pkg);
    if (found) return found;
  }
  return null;
}

function versionFromPackageLock(root) {
  return packageFromPackageLock(root)?.version ?? null;
}

function packageFromPackageLock(root) {
  const lock = readJson(join(root, 'package-lock.json'));
  if (!lock) return null;
  for (const name of CORE_UI_PACKAGES) {
    const entry = lock.packages?.[`node_modules/${name}`] || lock.dependencies?.[name];
    if (entry?.version) return { name, version: entry.version };
  }
  return null;
}

function versionFromTextLock(root) {
  return packageFromTextLock(root)?.version ?? null;
}

function packageFromTextLock(root) {
  for (const file of ['pnpm-lock.yaml', 'yarn.lock']) {
    const path = join(root, file);
    if (!existsSync(path)) continue;
    const text = readFileSync(path, 'utf8');
    const direct = text.match(/(@sdcorejs\/angular|@sd-angular\/core)[^\n\d]*(\d+\.\d+\.\d+)/);
    if (direct) return { name: direct[1], version: direct[2] };
    const quoted = text.match(/(@sdcorejs\/angular|@sd-angular\/core)[^@\n]*@(?:npm:)?(\d+\.\d+\.\d+)/);
    if (quoted) return { name: quoted[1], version: quoted[2] };
  }
  return null;
}

// Fetch `${SITE}/<rel>`; cache at `${CACHE_ROOT}/<rel>`; on network failure fall back to cache.
// `rel` is the full path under the docs site (e.g. `versions.json`, `21.0.7/index.json`).
async function getCached(rel) {
  const dest = safeCachePath(rel);
  try {
    const text = await httpText(`${SITE}/${rel}`);
    mkdirSync(dirname(dest), { recursive: true });
    writeFileSync(dest, text, 'utf8');
    return text;
  } catch (err) {
    if (existsSync(dest)) {
      process.stderr.write(`[core-docs-fetch] offline; using cached ${rel}\n`);
      return readFileSync(dest, 'utf8');
    }
    throw err;
  }
}

function safeCachePath(rel) {
  if (!rel || typeof rel !== 'string') {
    throw new Error('Invalid empty docs cache path');
  }
  if (rel.includes('\\') || isAbsolute(rel) || /^[a-zA-Z]:/.test(rel)) {
    throw new Error(`Unsafe docs cache path: ${rel}`);
  }
  const normalized = normalize(rel).replaceAll('\\', '/');
  if (normalized === '..' || normalized.startsWith('../') || normalized.includes('/../')) {
    throw new Error(`Unsafe docs cache path: ${rel}`);
  }
  return join(CACHE_ROOT, normalized);
}

// Read the installed Core UI package from the target project (either package name).
export function detectInstalledPackage(dir, { exact = false } = {}) {
  for (const name of CORE_UI_PACKAGES) {
    const p = join(dir, 'node_modules', name, 'package.json');
    if (existsSync(p)) {
      try { return { name, version: JSON.parse(readFileSync(p, 'utf8')).version }; } catch { /* ignore */ }
    }
  }
  const locked = packageFromPackageLock(dir);
  if (locked) return locked;
  // The legacy text-lock/declaration discovery extracts range minima. It is
  // useful for discovery but cannot establish an exact installed version.
  // With pnpm/yarn, use installed package metadata or an explicitly verified
  // --version; do not parse a specifier as a resolved package version.
  return exact ? null : packageFromTextLock(dir) || packageFromPackageJsons(dir);
}

// Read the installed Core UI version from the target project (either package name).
export function detectInstalledVersion(dir) {
  return detectInstalledPackage(dir)?.version ?? null;
}

// Version dirs already present in the cache (each with an index.json), newest first.
// The offline fallback when the registry itself can't be loaded (e.g. cache was seeded by an
// older script that never persisted versions.json).
function listCachedVersions() {
  try {
    return readdirSync(CACHE_ROOT, { withFileTypes: true })
      .filter(e => e.isDirectory() && /^\d+\.\d+\.\d+/.test(e.name))
      .map(e => e.name)
      .filter(v => existsSync(join(CACHE_ROOT, v, 'index.json')))
      .sort(cmpDesc);
  } catch { return []; }
}

// Order published versions best-first for a wanted version (the nearest-version policy):
// exact → newest patch of the SAME major → nearest OTHER major (by major distance, then newest
// patch). Falls back to newest-overall ordering when nothing is wanted. The caller tries each in
// turn and uses the first whose docs actually download, so an unfetchable version is skipped.
function orderCandidates(all, want) {
  const sorted = [...all].sort(cmpDesc); // newest first overall
  if (!want) return sorted;
  const wantMajor = Number(want.split('.')[0]);
  const exact = sorted.filter(v => v === want);
  const sameMajor = sorted.filter(v => v !== want && Number(v.split('.')[0]) === wantMajor); // newest patch first
  const otherMajor = sorted
    .filter(v => Number(v.split('.')[0]) !== wantMajor)
    .sort((a, b) => {
      const da = Math.abs(Number(a.split('.')[0]) - wantMajor);
      const db = Math.abs(Number(b.split('.')[0]) - wantMajor);
      return da - db || cmpDesc(a, b); // nearest major, then newest patch within it
    });
  return [...exact, ...sameMajor, ...otherMajor];
}

// Resolve an ORDERED list of candidate versions (best first) to try.
export function exactVersionCandidates({ installedPackage, version: explicitVersion } = {}) {
  const wanted = explicitVersion || installedPackage?.version;
  if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(wanted ?? '')) {
    throw new Error('An exact resolved Core UI version is required; inspect the installed package or lockfile.');
  }
  if (explicitVersion && installedPackage && explicitVersion !== installedPackage.version) {
    throw new Error('Explicit docs version conflicts with the detected Core UI version. Use installed source to resolve the conflict.');
  }
  return [wanted];
}

async function resolveVersionCandidates() {
  const installedPackage = detectInstalledPackage(cwd);
  if (requireInstalled && !installedPackage) {
    throw new Error(
      `Core UI package not installed in ${cwd}. Expected one of: ${CORE_UI_PACKAGES.join(', ')}. ` +
      'Classify this target as plain-angular or run an approved Core UI migration first.'
    );
  }
  const wantedVersion = version || installedPackage?.version;
  // Exact mode never consults nearest versions, even if the registry/cache has
  // another usable major. A missing exact index fails into local-source guidance.
  if (exactVersion) return exactVersionCandidates({ installedPackage: detectInstalledPackage(cwd, { exact: true }), version });

  // Load the published registry — cached, so version resolution survives offline use.
  let registry;
  try {
    registry = JSON.parse(await getCached('versions.json'));
  } catch (err) {
    // No network AND no cached registry. Resolve against version dirs already in the cache
    // (e.g. seeded by an older script that never persisted versions.json) so --list still works.
    const cached = listCachedVersions();
    if (!cached.length) {
      if (version) return [version]; // trust the literal; getCached will fail clearly
      throw err;
    }
    process.stderr.write('[core-docs-fetch] no remote registry; using cached docs versions.\n');
    return orderCandidates(cached, wantedVersion);
  }
  const all = registry.versions.map(v => v.version);
  // Target the explicit --version if given, else the project's installed Core UI version.
  // Resolution: exact published patch → newest patch of SAME major → nearest OTHER major → latest.
  // (The docs registry publishes only some patches, so a literal pin like 20.0.1 may not exist as a
  // docs build even though it's a valid npm pin — the nearest-version policy bridges that.)
  const want = wantedVersion;
  const ordered = orderCandidates(all, want);
  if (registry.latest && !ordered.includes(registry.latest)) ordered.push(registry.latest);
  return ordered.length ? ordered : all.sort(cmpDesc);
}

// Match a user-supplied component token against the index entries.
function resolveDoc(index, token) {
  const t = token.replace(/\.md$/, '');
  const docs = index.docs;
  return (
    docs.find(d => d.id === t || d.path === token) ||
    docs.find(d => d.id.endsWith('/' + t)) ||
    docs.find(d => d.id.split('/').pop() === t) ||
    docs.find(d => d.title.replace(/[`<>]/g, '') === t) ||
    docs.find(d => d.id.includes(t))
  );
}

async function main() {
  // Try candidate versions best-first; use the first whose index.json actually downloads.
  // This is the nearest-version fallback: a pinned version with no published/fetchable docs
  // falls through to the nearest one that can be pulled.
  const candidates = await resolveVersionCandidates();
  let v, index;
  for (const cand of candidates) {
    try {
      index = JSON.parse(await getCached(`${cand}/index.json`));
      v = cand;
      break;
    } catch (err) {
      process.stderr.write(`[core-docs-fetch] skipping docs version ${cand}: ${err.message}\n`);
    }
  }
  if (!index) throw new Error(`no fetchable docs version among: ${candidates.join(', ')}`);
  const installed = detectInstalledPackage(cwd);
  process.stderr.write(`[core-docs-fetch] requested=${version || installed?.version || 'unspecified'} resolved=${v} policy=${exactVersion ? 'exact' : 'nearest'}\n`);
  if (installed && installed.version !== v) {
    process.stderr.write('[core-docs-fetch] version mismatch: these docs are background only; verify APIs against installed source before use.\n');
  }

  if (doList || !comp) {
    process.stdout.write(`# Core UI docs version: ${v}\n`);
    process.stdout.write(`# Index: ${SITE}/${v}/index.json\n`);
    const byCat = {};
    for (const d of index.docs) (byCat[d.category] ||= []).push(d);
    for (const cat of Object.keys(byCat).sort()) {
      process.stdout.write(`\n## ${cat}\n`);
      for (const d of byCat[cat].sort((a, b) => a.id.localeCompare(b.id))) {
        process.stdout.write(`- ${d.title}  (${d.id})\n`);
      }
    }
    process.stdout.write(`\n# Fetch one: node core-docs-fetch.mjs <id>  (e.g. sd-button)\n`);
    return;
  }

  const doc = resolveDoc(index, comp);
  if (!doc) {
    process.stderr.write(`[core-docs-fetch] no Core UI doc matches "${comp}" in v${v}. Run --list.\n`);
    process.exit(2);
  }
  const md = await getCached(`${v}/${doc.path}`);
  if (MOJIBAKE.test(md)) {
    process.stderr.write(`[core-docs-fetch] MOJIBAKE in upstream ${doc.path} (v${v}); fix at source. Not using it.\n`);
    process.exit(3);
  }
  if (doPrint) {
    process.stdout.write(md);
  } else {
    process.stdout.write(join(CACHE_ROOT, v, doc.path) + '\n');
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch(err => {
    process.stderr.write(`[core-docs-fetch] failed: ${err.message}\n`);
    process.stderr.write('Run from the target Angular project or pass --cwd <target-project>. If remote docs are unavailable, seed the cache or use local project evidence.\n');
    process.exit(1);
  });
}

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const catalog = JSON.parse(readFileSync(new URL('./catalog.json', import.meta.url), 'utf8'));

/**
 * Select a bounded set of references from an already classified UI task.
 * This is exact topic lookup, not natural-language dispatch or API discovery.
 * Only catalog metadata is read; the caller reads selected Markdown on demand.
 */
export function selectUiuxReferences(input) {
  const invalid = (message) => { throw new Error(`UI/UX selection: ${message}`); };
  if (!input || typeof input !== 'object' || Array.isArray(input)) invalid('expected an object');
  if (!catalog.tasks.includes(input.task)) invalid('unknown task');
  if (['qa', 'non-ui'].includes(input.task)) {
    return { status: 'not-applicable', references: [], unmatched_topics: [], reason: 'No UI workflow is required.' };
  }
  if (typeof input.surface !== 'string' || !input.surface.trim()) invalid('surface is required');
  if (input.topics !== undefined && (!Array.isArray(input.topics) || input.topics.some((topic) => typeof topic !== 'string' || !topic.trim()))) {
    invalid('topics must be nonempty strings in an array');
  }
  const knownSurface = Object.hasOwn(catalog.surfaces, input.surface);
  const topics = [...new Set(input.topics?.length ? input.topics :
    input.task === 'design-new' && knownSurface ? catalog.surfaces[input.surface] : [])];
  const references = knownSurface ? catalog.references.filter((entry) =>
    (entry.surfaces.includes('*') || entry.surfaces.includes(input.surface)) &&
    entry.topics.some((topic) => topics.includes(topic))) : [];
  const unmatched = topics.filter((topic) => !references.some((entry) => entry.topics.includes(topic)));
  return {
    status: !references.length ? 'no-match' : unmatched.length ? 'partial-match' : 'matched',
    references: references.map(({ id, path, rule_ids }) => ({ id, path, rule_ids: [...rule_ids] })),
    unmatched_topics: unmatched,
    reason: !references.length || unmatched.length
      ? 'No verified match for the unresolved scope; use explicitly labeled general guidance from index.md and current UI evidence.'
      : 'Read only these references; applicability and verification remain the caller responsibility.',
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    const [surface, task, ...topics] = process.argv.slice(2);
    process.stdout.write(`${JSON.stringify(selectUiuxReferences({ surface, task, topics }), null, 2)}\n`);
  } catch (error) {
    process.stderr.write(`${error.message}\nUsage: node select-references.mjs <surface> <task> [topic ...]\n`);
    process.exitCode = 1;
  }
}

import {
  CONSISTENCY_FINDING_KINDS,
  validateConsistencyFinding,
} from './convention-contract.mjs';
import { systemRegistry } from './system-registry.mjs';

const SEVERITIES = new Set(['Critical', 'High', 'Important', 'Medium', 'Minor', 'Low', 'Info']);

const REVIEW_DIMENSIONS = new Map(
  systemRegistry.review_dimensions.map((dimension) => [dimension.id, dimension]),
);

/**
 * How much of the consistency dimension a requested review actually runs.
 *
 * The distinction matters because a consistency audit is expensive and
 * opinionated. Someone who asked for a security review wants authorization and
 * injection findings, not a naming inventory, so a security-only request may
 * only surface a consistency issue when it changes the security answer - for
 * example a permission code that two layers spell differently.
 */
export function resolveConsistencyScope(dimensions = []) {
  const requested = dimensions.filter((dimension) => REVIEW_DIMENSIONS.has(dimension));
  const scopes = new Set(
    requested.map((dimension) => REVIEW_DIMENSIONS.get(dimension).consistency_scope),
  );
  if (scopes.has('complete')) {
    return { scope: 'complete', reason: 'consistency or ALL was requested directly' };
  }
  if (scopes.has('applicable')) {
    return { scope: 'applicable', reason: 'code review includes applicable consistency checks' };
  }
  if (scopes.has('structural')) {
    return {
      scope: 'structural',
      reason: 'architecture review includes structural and cross-layer consistency checks',
    };
  }
  if (requested.length === 0) {
    return { scope: 'none', reason: 'no recognized review dimension was requested' };
  }
  return {
    scope: 'dimension-affecting-only',
    reason: 'narrow dimension reports consistency only where it affects that dimension',
  };
}

function finding(id, severity, kind, observation, requiredFix) {
  return {
    id,
    severity,
    kind,
    evidence: observation.evidence ?? observation.path ?? observation.logical_id,
    locator: observation.locator ?? observation.path ?? observation.logical_id,
    repository_id: observation.repository_id ?? null,
    module_id: observation.module_id ?? null,
    impact: observation.impact,
    required_fix: requiredFix,
  };
}

export function evaluateReviewContract(context) {
  const blockers = [];
  const track = systemRegistry.tracks.find(({ id }) => id === context?.subject_track);
  if (context?.schema_version !== 1) blockers.push('review schema_version must be 1');
  if (!track) {
    blockers.push(`unsupported review track: ${context?.subject_track}`);
  } else if (context.review_profile !== track.review_profile) {
    blockers.push(
      `review profile ${context.review_profile} does not match registry profile ${track.review_profile}`,
    );
  }
  if (context?.mode !== 'read-only') blockers.push('review mode must be read-only');
  if ((context?.write_actions ?? []).length > 0) {
    blockers.push('read-only review cannot contain write actions');
  }

  const requestedDimensions = context?.dimensions ?? [];
  for (const dimension of requestedDimensions) {
    if (!REVIEW_DIMENSIONS.has(dimension)) {
      blockers.push(`unsupported review dimension: ${dimension}`);
    }
  }
  const consistency = resolveConsistencyScope(requestedDimensions);
  // The dimensions the user asked for survive verbatim. A consistency issue is
  // reported as `consistency`, never relabelled into generic code style, and a
  // narrow request is never widened into a full audit behind the user's back.
  const consistencyReportingAllowed = consistency.scope !== 'none';

  const findings = [];
  let sequence = 1;
  for (const item of context?.reported_findings ?? []) {
    if (
      !SEVERITIES.has(item.severity) ||
      !item.evidence ||
      !item.locator ||
      !item.repository_id ||
      !item.impact ||
      !item.required_fix
    ) {
      blockers.push(`finding ${item.id ?? sequence} does not satisfy the durable schema`);
      continue;
    }
    // UI/UX observations retain the existing durable finding/report shape.
    // Additional evidence fields apply only to explicitly classified UI work.
    if (item.kind === 'uiux' || item.uiux !== undefined) {
      const uiux = item.uiux;
      const text = (value) => typeof value === 'string' && value.trim().length > 0;
      if (!uiux || !['functional', 'accessibility', 'convention', 'aesthetic'].includes(uiux.classification) ||
        !['source', 'rendered', 'interaction'].includes(uiux.evidence_kind) ||
        !text(uiux.rule_id) || !text(uiux.verification) ||
        (uiux.evidence_kind === 'source' && !text(uiux.limitation))) {
        blockers.push(`finding ${item.id ?? sequence} lacks UI/UX classification, evidence scope, verification, or source-only limitation`);
        continue;
      }
      if (uiux.classification === 'aesthetic' &&
        (!['Minor', 'Low', 'Info'].includes(item.severity) || item.gate === 'REQUIRED' ||
          item.repair_tier === 'auto' || item.eligible_for_automatic_repair === true)) {
        blockers.push(`finding ${item.id ?? sequence} cannot make an aesthetic preference blocking`);
        continue;
      }
      if (!REVIEW_DIMENSIONS.has(item.dimension) ||
        (!requestedDimensions.includes(item.dimension) && !requestedDimensions.includes('ALL') &&
          !(requestedDimensions.includes('site-audit') && ['code', 'accessibility'].includes(item.dimension)))) {
        blockers.push(`finding ${item.id ?? sequence} expands a narrow review into an unrequested UI/UX dimension`);
        continue;
      }
      const uiuxDimension = { functional: 'code', accessibility: 'accessibility', convention: 'consistency', aesthetic: 'code' };
      if (item.dimension !== uiuxDimension[uiux.classification]) {
        blockers.push(`finding ${item.id ?? sequence} has a contradictory UI/UX classification and dimension`);
        continue;
      }
      if (uiux.classification === 'convention' && !CONSISTENCY_FINDING_KINDS.includes(item.finding_kind)) {
        blockers.push(`finding ${item.id ?? sequence} must use the existing consistency finding contract`);
        continue;
      }
    }
    // Match on a declared consistency kind, not on the mere presence of a
    // `finding_kind` field. A truthy check would drag any finding that happens
    // to carry that field - including a security finding from another producer -
    // into the consistency gate and reject it as an audit that was never asked
    // for.
    const reportsConsistency =
      item.dimension === 'consistency' || CONSISTENCY_FINDING_KINDS.includes(item.finding_kind);
    if (reportsConsistency) {
      if (!consistencyReportingAllowed) {
        blockers.push(
          `finding ${item.id ?? sequence} reports consistency but no requested dimension covers it`,
        );
        continue;
      }
      if (consistency.scope === 'dimension-affecting-only' && item.affects_requested_dimension !== true) {
        blockers.push(
          `finding ${item.id ?? sequence} expands a narrow review into a consistency audit`,
        );
        continue;
      }
      const consistencyValidation = validateConsistencyFinding(item);
      if (!consistencyValidation.ok) {
        blockers.push(
          `finding ${item.id ?? sequence} is not a valid consistency finding: ${consistencyValidation.errors.join('; ')}`,
        );
        continue;
      }
    }
    findings.push({ ...item });
    sequence += 1;
  }

  const conventionContext = context?.convention_context ?? null;
  if (conventionContext) {
    if (conventionContext.mode !== 'read-only') {
      blockers.push('convention_context carried by review must stay read-only');
    }
    if ((conventionContext.write_actions ?? []).length > 0) {
      blockers.push('convention_context carried by review cannot contain write actions');
    }
    if (conventionContext.persistence?.performed === true) {
      blockers.push('review must not perform convention persistence');
    }
  }

  const artifacts = context?.artifacts ?? [];
  for (const artifact of artifacts) {
    if (artifact.repository_id !== artifact.owner_repository_id) {
      findings.push(
        finding(
          `R${sequence++}`,
          'High',
          'misplaced-owner-artifact',
          {
            ...artifact,
            impact: 'Module-owned editable artifact is stored in the wrong repository.',
          },
          'Move authoring to the semantic owner and remove the misplaced editable copy.',
        ),
      );
    }
    if (
      artifact.approved_hash &&
      artifact.current_hash &&
      artifact.approved_hash !== artifact.current_hash
    ) {
      findings.push(
        finding(
          `R${sequence++}`,
          'High',
          'mutated-approved-artifact',
          {
            ...artifact,
            impact: 'Approved artifact hash no longer matches its approval.',
          },
          'Restore the approved bytes or return through approval before implementation.',
        ),
      );
    }
  }
  const editableByLogicalId = new Map();
  for (const artifact of artifacts.filter(({ editable }) => editable === true)) {
    const group = editableByLogicalId.get(artifact.logical_id) ?? [];
    group.push(artifact);
    editableByLogicalId.set(artifact.logical_id, group);
  }
  for (const [logicalId, group] of editableByLogicalId) {
    if (new Set(group.map(({ repository_id: repositoryId }) => repositoryId)).size > 1) {
      findings.push(
        finding(
          `R${sequence++}`,
          'High',
          'duplicate-editable-source',
          {
            logical_id: logicalId,
            repository_id: group[0].repository_id,
            module_id: group[0].module_id,
            evidence: group.map(({ repository_id: repositoryId, path }) => `${repositoryId}:${path}`).join(', '),
            impact: 'Portal and module contain competing editable sources.',
          },
          'Keep one editable source in the semantic owner and generate/aggregate elsewhere.',
        ),
      );
    }
  }

  for (const evidence of context?.test_evidence ?? []) {
    const currentRevision = context.current_revision_map?.[evidence.repository_id];
    const pinnedRevision =
      evidence.module_id == null
        ? evidence.source_revision
        : context.portal_pinned_module_revision_map?.[evidence.module_id];
    if (
      evidence.status !== 'current' ||
      evidence.source_revision !== currentRevision ||
      evidence.source_revision !== pinnedRevision
    ) {
      findings.push(
        finding(
          `R${sequence++}`,
          'High',
          'stale-evidence',
          {
            ...evidence,
            locator: evidence.evidence_ref,
            impact: 'Evidence does not prove the reviewed current/pinned source.',
          },
          'Re-run the exact command on the current owner revision and matching portal pin.',
        ),
      );
    }
  }

  for (const provider of context?.provider_evidence ?? []) {
    if (provider.production_required === true && provider.provider_kind === 'fake') {
      findings.push(
        finding(
          `R${sequence++}`,
          'Critical',
          'fake-production-provider',
          {
            ...provider,
            locator: provider.contract_path,
            evidence: provider.evidence_ref,
            impact: 'A fake provider hides an unresolved production boundary.',
          },
          'Validate the real production provider directly; keep doubles test-only.',
        ),
      );
    }
  }

  return {
    schema_version: 1,
    registry_version: systemRegistry.registry_version,
    status: blockers.length === 0 ? 'reviewed' : 'blocked',
    read_only_proven: context?.mode === 'read-only' && (context?.write_actions ?? []).length === 0,
    subject_track: context?.subject_track ?? null,
    review_profile: context?.review_profile ?? null,
    owner_repository_id: context?.owner_repository_id ?? null,
    execution_host_repository_id: context?.execution_host_repository_id ?? null,
    requested_dimensions: [...requestedDimensions],
    consistency_scope: consistency.scope,
    consistency_scope_reason: consistency.reason,
    convention_context_read_only:
      conventionContext == null
        ? null
        : conventionContext.mode === 'read-only' &&
          (conventionContext.write_actions ?? []).length === 0,
    findings,
    blockers,
  };
}

